package com.bank.java8;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

class Java8To11Test {

    // Simulates the decision: is this class from a module removed in Java 11?
    boolean removedInJava11(String fqcn) {
        return fqcn.startsWith("javax.xml.bind")
            || fqcn.startsWith("javax.xml.ws")
            || fqcn.startsWith("javax.activation")
            || fqcn.startsWith("org.omg.CORBA");
    }

    @Test
    void identifiesRemovedModules() {
        assertThat(removedInJava11("javax.xml.bind.JAXBContext")).isTrue();
        assertThat(removedInJava11("org.omg.CORBA.ORB")).isTrue();
        assertThat(removedInJava11("java.util.stream.Stream")).isFalse();
    }
}
